import { apiRequest } from './api'

/** Authenticated media. Files are served by the owner-only /api/media/<id>/file/ view. */
export const mediaApi = {
  upload(file, purpose = 'general') {
    const body = new FormData()
    body.append('file', file)
    body.append('purpose', purpose)
    return apiRequest('POST', '/media/', { body })
  },
}

export function mediaFileUrl(id) {
  return id ? `/api/media/${id}/file/` : ''
}

/** QR codes are generated by our own backend (local `qrcode` library), never by an external service. */
export function qrImageUrl(link, ec = 'M') {
  return link ? `/api/qr/?data=${encodeURIComponent(link)}&ec=${ec}` : ''
}
